def get_soundex(name):
    if not name:
        return ""

    # Normalize
    name = name.upper()
    first_letter = name[0]

    # Step 1: Remove h and w except first letter
    # We construct a new string: first_letter + (rest with h/w removed)
    rest = name[1:].replace('H', '').replace('W', '')
    s = first_letter + rest

    # Step 2: Replace consonants with digits
    # Mapping
    table = str.maketrans(
        "BFPVCGJKQSXZDTLMNR",
        "111122222222334556"
    )
    # We translate only consonants. Vowels and others stay.
    # But maketrans maps specific chars. Let's do it manually to be safe with non-alpha.
    mapped = []
    for char in s:
        if char in "BFPV":
            mapped.append('1')
        elif char in "CGJKQSXZ":
            mapped.append('2')
        elif char in "DT":
            mapped.append('3')
        elif char == 'L':
            mapped.append('4')
        elif char in "MN":
            mapped.append('5')
        elif char == 'R':
            mapped.append('6')
        else:
            mapped.append(char)

    s = "".join(mapped)

    # Step 3: Replace adjacent same digits with one digit
    # Iterate and skip if current is digit and same as previous digit
    collapsed = []
    prev = None
    for char in s:
        if char.isdigit():
            if char == prev:
                continue
            collapsed.append(char)
            prev = char
        else:
            collapsed.append(char)
            prev = char # Reset prev to non-digit so next digit doesn't match

    s = "".join(collapsed)

    # Step 4: Remove vowels (A, E, I, O, U, Y) except first letter
    vowels = "AEIOUY"
    result_chars = [s[0]]
    for char in s[1:]:
        if char not in vowels:
            result_chars.append(char)

    s = "".join(result_chars)

    # Step 5: If first symbol is digit, replace with saved letter
    # Since we kept the original first letter in step 1 and didn't remove it in step 4,
    # s[0] might be a digit if the original first letter was a consonant.
    if s[0].isdigit():
        s = first_letter + s[1:]
    else:
        s = first_letter + s[1:] # Ensure first letter is the original one

    # Step 6: Pad with zeros or truncate to 1 letter + 3 digits
    # Extract digits
    digits = [c for c in s[1:] if c.isdigit()]

    if len(digits) < 3:
        digits.extend(['0'] * (3 - len(digits)))
    else:
        digits = digits[:3]

    return first_letter + "".join(digits)

