def calculate_bulls_cows(secret, guess):
    """Calculates bulls and cows for a given secret and guess."""
    bulls = 0
    cows = 0
    s_list = list(secret)
    g_list = list(guess)

    # Count bulls
    for i in range(4):
        if s_list[i] == g_list[i]:
            bulls += 1
            s_list[i] = None
            g_list[i] = None

    # Count cows
    for i in range(4):
        if g_list[i] is not None and g_list[i] in s_list:
            cows += 1
            s_list[s_list.index(g_list[i])] = None

    return bulls, cows

