import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    out = []

    for _ in range(t):
        try:
            n = int(next(iterator))
        except StopIteration:
            break

        # Maximum chain length is n
        out.append(str(n))

        # Start with identity permutation
        p = list(range(1, n + 1))
        out.append(" ".join(map(str, p)))

        # Generate the chain by swapping the first element with the i-th element
        # Step 1: Swap index 0 and 1 (reduces fixed points by 2)
        # Step 2..n-1: Swap index 0 and i (reduces fixed points by 1)
        for i in range(1, n):
            p[0], p[i] = p[i], p[0]
            out.append(" ".join(map(str, p)))

    sys.stdout.write("\n".join(out) + "\n")

if __name__ == "__main__":
    main()
